INSERT INTO dnd35_feats
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   repeatable,choice_kind,repeatability_text,normal_text,special_text)
SELECT 'elh-feat-'||d.slug,'elh-3.0','50-69',d.slug,d.name,d.description,d.description,0,NULL,1,
       d.repeatable,d.choice_kind,d.repeatability_text,NULL,NULL
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_feats f WHERE f.slug=d.slug AND f.owner_user_id IS NULL);